import type { JSX, SVGProps } from "react";

export type EyeIconProps = Omit<SVGProps<SVGSVGElement>, "color"> & {
  size?: number;
  color?: string;
  testID?: string;
};

/**
 * Lucide `Eye` for the web and for the DOM-based tests. The native twin is
 * `Eye.native.tsx`, generated by the official Tamagui v3 command
 * (`npx @tamagui/cli icons add Eye`) on top of `react-native-svg`.
 */
export function Eye({
  size = 24,
  color = "currentColor",
  testID,
  ...rest
}: EyeIconProps): JSX.Element {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
      aria-hidden="true"
      focusable="false"
      data-testid={testID}
    >
      <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z" stroke={color} />
      <circle cx="12" cy="12" r="3" stroke={color} />
    </svg>
  );
}

Eye.displayName = "Eye";
